package main

import (
	"encoding/binary"
	"log"
	"net/http"
	"sync"

	"github.com/gorilla/websocket"
)

const (
	MaxMessageSize = 65536
	HeaderSize     = 4
	BufferPool     = 256
)

var upgrader = websocket.Upgrader{
	ReadBufferSize:  1024,
	WriteBufferSize: 1024,
	CheckOrigin: func(r *http.Request) bool {
		return true // Accept all origins for internal service
	},
}

type MessageBuffer struct {
	data [512]byte
	used int
}

var bufferPool = sync.Pool{
	New: func() interface{} {
		return &MessageBuffer{}
	},
}

// parseFrameHeader extracts the payload length from a custom binary protocol header
// Protocol: [2 bytes magic 0xFE 0xED] [2 bytes payload length] [payload]
func parseFrameHeader(raw []byte) (uint16, []byte) {
	if len(raw) < HeaderSize {
		return 0, nil
	}
	if raw[0] != 0xFE || raw[1] != 0xED {
		return 0, nil
	}
	payloadLen := binary.BigEndian.Uint16(raw[2:4])
	return payloadLen, raw[HeaderSize:]
}

// processMessage handles incoming binary frames from trusted internal clients
// The service processes telemetry data from edge nodes in known network segments
func processMessage(msg []byte) []byte {
	payloadLen, payload := parseFrameHeader(msg)
	if payloadLen == 0 || payload == nil {
		return nil
	}

	buf := bufferPool.Get().(*MessageBuffer)
	defer bufferPool.Put(buf)

	// VULNERABILITY: payloadLen is attacker-controlled uint16 (max 65535)
	// but buf.data is only [512]byte. No bounds check before copy.
	// This causes a stack buffer overflow when payloadLen > 512
	copy(buf.data[:payloadLen], payload[:payloadLen])
	buf.used = int(payloadLen)

	// Process the telemetry frame (simplified)
	response := make([]byte, buf.used)
	for i := 0; i < buf.used; i++ {
		response[i] = buf.data[i] ^ 0x55 // XOR transform for ack
	}
	return response
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	conn.SetReadLimit(MaxMessageSize)

	for {
		msgType, msg, err := conn.ReadMessage()
		if err != nil {
			break
		}
		if msgType != websocket.BinaryMessage {
			continue
		}

		response := processMessage(msg)
		if response != nil {
			conn.WriteMessage(websocket.BinaryMessage, response)
		}
	}
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/ws/telemetry", handleWebSocket)
	http.HandleFunc("/health", healthCheck)

	log.Println("Starting telemetry WebSocket service on :8443")
	log.Fatal(http.ListenAndServe(":8443", nil))
}
